628	    private static async Task WithIsolatedQuadbrainTemp(Func<string, Task> body)
629	    {
630	        await TempEnvLock.WaitAsync(TestContext.Current.CancellationToken).ConfigureAwait(true);
631	        var previousQuad = Environment.GetEnvironmentVariable("MCPSERVER_QUADBRAIN_CLI_TEMP");
632	        var previousOneShot = Environment.GetEnvironmentVariable("MCPSERVER_ONESHOT_TEMP");
633	        var temp = Path.Combine(Path.GetTempPath(), "qbt-" + Guid.NewGuid().ToString("N"));
634	        Directory.CreateDirectory(temp);
635	        try
636	        {
637	            Environment.SetEnvironmentVariable("MCPSERVER_QUADBRAIN_CLI_TEMP", temp);
638	            Environment.SetEnvironmentVariable("MCPSERVER_ONESHOT_TEMP", null);
639	            await body(temp).ConfigureAwait(true);
640	        }
641	        finally
642	        {
643	            Environment.SetEnvironmentVariable("MCPSERVER_QUADBRAIN_CLI_TEMP", previousQuad);
644	            Environment.SetEnvironmentVariable("MCPSERVER_ONESHOT_TEMP", previousOneShot);
645	            try
646	            {
647	                Directory.Delete(temp, recursive: true);
648	            }
649	            catch (IOException)
650	            {
651	            }
652	
653	            TempEnvLock.Release();
654	        }
655	    }
