692	    private sealed class RecordingSpawner(
693	        string stdout = "",
694	        string outputBody = "",
695	        int exitCode = 0,
696	        string stderr = "") : IProcessSpawner
697	    {
698	        public List<ProcessStartInfo> StartInfos { get; } = [];
699	
700	        public List<(int ExitCode, string Stdout, string Stderr)>? Script { get; init; }
701	
702	        private int _scriptIndex;
703	
704	        public ISpawnedProcess Spawn(ProcessStartInfo startInfo)
705	        {
706	            StartInfos.Add(Clone(startInfo));
707	            var outputPath = GetArgumentAfter(startInfo, "-o");
708	            if (!string.IsNullOrWhiteSpace(outputPath) && outputBody.Length > 0)
709	                File.WriteAllText(outputPath, outputBody, Encoding.UTF8);
710	
711	            if (Script is { Count: > 0 } script && _scriptIndex < script.Count)
712	            {
713	                var step = script[_scriptIndex++];
714	                return new FakeProcess(step.Stdout, step.Stderr, step.ExitCode);
715	            }
716	
717	            return new FakeProcess(stdout, stderr, exitCode);
718	        }
719	
720	        private static string? GetArgumentAfter(ProcessStartInfo startInfo, string name)
721	        {
722	            var index = startInfo.ArgumentList.IndexOf(name);
723	            return index >= 0 && index + 1 < startInfo.ArgumentList.Count
724	                ? startInfo.ArgumentList[index + 1]
725	                : null;
726	        }
727	
728	        private static ProcessStartInfo Clone(ProcessStartInfo source)
729	        {
730	            var copy = new ProcessStartInfo
731	            {
732	                FileName = source.FileName,
733	                WorkingDirectory = source.WorkingDirectory,
734	                RedirectStandardInput = source.RedirectStandardInput,
735	            };
736	            foreach (var argument in source.ArgumentList)
737	                copy.ArgumentList.Add(argument);
738	            // A fresh ProcessStartInfo inherits the current process environment.
739	            // Copying source entries does not drop keys the product removed
740	            // (GROK_PLUGIN_ROOT / GROK_HOME). Record the source environment only.
741	            var sourceKeys = new HashSet<string>(source.Environment.Keys, StringComparer.OrdinalIgnoreCase);
742	            var inherited = new List<string>();
743	            foreach (var key in copy.Environment.Keys)
744	            {
745	                if (!sourceKeys.Contains(key))
746	                    inherited.Add(key);
747	            }
748	
749	            foreach (var key in inherited)
750	                copy.Environment.Remove(key);
751	            foreach (var (key, value) in source.Environment)
752	                copy.Environment[key] = value;
753	            return copy;
754	        }
755	    }
