245	    internal sealed class CapturingProcessSpawner(
246	        int exitCode,
247	        string outputBody = "",
248	        string stdout = "",
249	        string stderr = "",
250	        bool waitForCancellation = false) : IProcessSpawner
251	    {
252	        public ProcessStartInfo? StartInfo { get; private set; }
253	
254	        public string? OutputLastMessagePath { get; private set; }
255	
256	        public string? OutputSchemaPath { get; private set; }
257	
258	        public string? OutputSchemaJson { get; private set; }
259	
260	        public string? CapturedStandardInput => LastProcess?.StandardInputText;
261	
262	        private FakeSpawnedProcess? LastProcess { get; set; }
263	
264	        public ISpawnedProcess Spawn(ProcessStartInfo startInfo)
265	        {
266	            StartInfo = startInfo;
267	            OutputLastMessagePath = GetArgumentValue(startInfo, "-o");
268	            OutputSchemaPath = GetArgumentValue(startInfo, "--output-schema");
269	            if (!string.IsNullOrWhiteSpace(OutputSchemaPath) && File.Exists(OutputSchemaPath))
270	            {
271	                OutputSchemaJson = File.ReadAllText(OutputSchemaPath, Encoding.UTF8);
272	            }
273	
274	            if (!string.IsNullOrWhiteSpace(OutputLastMessagePath) && outputBody.Length > 0)
275	            {
276	                File.WriteAllText(OutputLastMessagePath, outputBody, Encoding.UTF8);
277	            }
278	
279	            LastProcess = new FakeSpawnedProcess(exitCode, stdout, stderr, waitForCancellation);
280	            return LastProcess;
281	        }
282	
283	        public bool HasArgument(string name)
284	        {
285	            if (StartInfo is null)
286	                return false;
287	
288	            return StartInfo.ArgumentList.Any(argument => string.Equals(argument, name, StringComparison.Ordinal))
289	                || StartInfo.ArgumentList.Any(argument => Regex.IsMatch(
290	                    argument,
291	                    "(^|\\s)" + Regex.Escape(name) + "(\\s|$)",
292	                    RegexOptions.CultureInvariant,
293	                    TimeSpan.FromMilliseconds(100)));
294	        }
295	
296	        private static string? GetArgumentValue(ProcessStartInfo startInfo, string name)
297	        {
298	            for (var index = 0; index < startInfo.ArgumentList.Count - 1; index++)
299	            {
300	                if (string.Equals(startInfo.ArgumentList[index], name, StringComparison.Ordinal))
301	                    return startInfo.ArgumentList[index + 1];
302	            }
303	
304	            var pattern = Regex.Escape(name) + "\\s+(?:\"(?<quoted>[^\"]+)\"|(?<plain>\\S+))";
305	            foreach (var argument in startInfo.ArgumentList)
306	            {
307	                var match = Regex.Match(argument, pattern, RegexOptions.CultureInvariant, TimeSpan.FromMilliseconds(100));
308	                if (match.Success)
309	                    return match.Groups["quoted"].Success ? match.Groups["quoted"].Value : match.Groups["plain"].Value;
310	            }
311	
312	            return null;
313	        }
314	    }
