1	using Xunit;
2	
3	namespace QBrainAi.Support.Mcp.Tests.TestSupport;
4	
5	/// <summary>
6	/// The process-environment variables the CLI strategies read to choose their temporary folder, in each strategy's
7	/// fallback order: <c>CliBrainSlotChatClient</c> reads MCPSERVER_QUADBRAIN_CLI_TEMP then MCPSERVER_ONESHOT_TEMP;
8	/// <c>CodexCliAgentExecutionStrategy</c> reads MCPSERVER_CODEX_ONESHOT_TEMP then MCPSERVER_CODEX_TRIAGE_TEMP;
9	/// <c>OneShotCliAgentExecutionStrategy</c> reads MCPSERVER_ONESHOT_TEMP, MCPSERVER_CODEX_ONESHOT_TEMP, then
10	/// MCPSERVER_CODEX_TRIAGE_TEMP; <c>GrokCliAgentExecutionStrategy</c> reads MCPSERVER_GROK_ONESHOT_TEMP then
11	/// MCPSERVER_ONESHOT_TEMP. A test that reaches one of them sets every name of the chain and restores it
12	/// (TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26; operator: "Strengthen AC, move 14
13	/// (Recommended)"; hostile validation finding R6-F1). Shared by the three strategy test classes.
14	/// </summary>
15	internal static class CliTempVariables
16	{
17	    /// <summary>Every name of the four fallback chains, once each.</summary>
18	    internal static IReadOnlyList<string> Names { get; } =
19	    [
20	        "MCPSERVER_QUADBRAIN_CLI_TEMP",
21	        "MCPSERVER_ONESHOT_TEMP",
22	        "MCPSERVER_CODEX_ONESHOT_TEMP",
23	        "MCPSERVER_CODEX_TRIAGE_TEMP",
24	        "MCPSERVER_GROK_ONESHOT_TEMP",
25	    ];
26	
27	    /// <summary>
28	    /// Runs <paramref name="body"/> with every name of <see cref="Names"/> pointing at one new folder under the
29	    /// official temporary folder, then restores every name to its earlier value (an unset name stays unset) and
30	    /// deletes the folder, also when the body throws. Callers belong to <see cref="ProcessEnvironmentCollection"/>.
31	    /// </summary>
32	    /// <param name="body">The test body; it receives the folder.</param>
33	    /// <returns>A task that completes when the body has run and the variables are restored.</returns>
34	    internal static async Task RunWithTestFolderAsync(Func<string, Task> body)
35	    {
36	        ArgumentNullException.ThrowIfNull(body);
37	        var previous = Snapshot();
38	        var folder = Path.Combine(Path.GetTempPath(), "qbt-cli-temp-" + Guid.NewGuid().ToString("N"));
39	        Directory.CreateDirectory(folder);
40	        try
41	        {
42	            foreach (var name in Names)
43	                Environment.SetEnvironmentVariable(name, folder);
44	            await body(folder).ConfigureAwait(true);
45	        }
46	        finally
47	        {
48	            foreach (var (name, value) in previous)
49	                Environment.SetEnvironmentVariable(name, value);
50	            try
51	            {
52	                Directory.Delete(folder, recursive: true);
53	            }
54	            catch (IOException)
55	            {
56	            }
57	        }
58	    }
59	
60	    /// <summary>Reads the current value of every name of <see cref="Names"/> from the process environment.</summary>
61	    /// <returns>The values by name, null for an unset name.</returns>
62	    internal static Dictionary<string, string?> Snapshot() =>
63	        Names.ToDictionary(name => name, name => Environment.GetEnvironmentVariable(name), StringComparer.Ordinal);
64	
65	    /// <summary>
66	    /// Asserts that a snapshot of the variables holds every name of <see cref="Names"/> and that each one points at
67	    /// <paramref name="folder"/>.
68	    /// </summary>
69	    /// <param name="observed">The variable values seen, by name.</param>
70	    /// <param name="folder">The folder every name must point at.</param>
71	    internal static void AssertAllAt(IReadOnlyDictionary<string, string?> observed, string folder)
72	    {
73	        ArgumentNullException.ThrowIfNull(observed);
74	        foreach (var name in Names)
75	        {
76	            Assert.True(observed.TryGetValue(name, out var value), $"{name} was not observed.");
77	            Assert.Equal(folder, value);
78	        }
79	    }
80	
81	    /// <summary>
82	    /// Asserts that a snapshot of the variables points the name a strategy reads first, <paramref name="primaryName"/>,
83	    /// at <paramref name="folder"/> and every other name of <see cref="Names"/> at a different folder,
84	    /// <paramref name="fallbackFolder"/>, so a test that asserts on <paramref name="folder"/> proves the primary name
85	    /// won over a set fallback.
86	    /// </summary>
87	    /// <param name="observed">The variable values seen, by name.</param>
88	    /// <param name="primaryName">The name the strategy under test reads first; one of <see cref="Names"/>.</param>
89	    /// <param name="folder">The folder the primary name must point at.</param>
90	    /// <param name="fallbackFolder">The folder every other name must point at; not <paramref name="folder"/>.</param>
91	    internal static void AssertChainAt(IReadOnlyDictionary<string, string?> observed, string primaryName, string folder, string fallbackFolder)
92	    {
93	        ArgumentNullException.ThrowIfNull(observed);
94	        Assert.Contains(primaryName, Names);
95	        Assert.NotEqual(folder, fallbackFolder);
96	        foreach (var name in Names)
97	        {
98	            Assert.True(observed.TryGetValue(name, out var value), $"{name} was not observed.");
99	            Assert.Equal(name == primaryName ? folder : fallbackFolder, value);
100	        }
101	    }
102	
103	    /// <summary>
104	    /// Asserts that every name of <see cref="Names"/> holds the same value after a run as before it, an unset name
105	    /// included.
106	    /// </summary>
107	    /// <param name="before">The values before the run, by name.</param>
108	    /// <param name="after">The values after the run, by name.</param>
109	    internal static void AssertRestored(IReadOnlyDictionary<string, string?> before, IReadOnlyDictionary<string, string?> after)
110	    {
111	        ArgumentNullException.ThrowIfNull(before);
112	        ArgumentNullException.ThrowIfNull(after);
113	        foreach (var name in Names)
114	        {
115	            Assert.True(before.TryGetValue(name, out var expected), $"{name} was not recorded before the run.");
116	            Assert.True(after.TryGetValue(name, out var actual), $"{name} was not recorded after the run.");
117	            Assert.Equal(expected, actual);
118	        }
119	    }
120	}
