1	using Xunit;
2	using static QBrainAi.Support.Mcp.Tests.TestSupport.CliTempVariables;
3	
4	namespace QBrainAi.Support.Mcp.Tests.TestSupport;
5	
6	/// <summary>
7	/// Tests the shared CLI temporary-folder variable support of <see cref="CliTempVariables"/>: its name list matches the
8	/// four strategies' fallback chains, and its snapshot assertions accept a run that pointed every name at the test
9	/// folder and restored every name, and reject one that missed or mis-set a name.
10	/// </summary>
11	/// <remarks>
12	/// Requirement coverage: TR-MCP-USECASE-018 AC-006 and TR-MCP-USECASE-019 AC-008 as amended 2026-10-26 ("sets and
13	/// restores every variable its assertions or the code it calls depend on, every name of a fallback chain the code
14	/// reads"; operator: "Strengthen AC, move 14 (Recommended)"; hostile validation finding R6-F1). Test data: scripted
15	/// snapshots (dictionaries of name to value); these mock gate controls read and write no process environment, so
16	/// they are unit tests. The class runs in <see cref="ProcessEnvironmentCollection"/> because its binding tests write
17	/// the process environment; those are integration tests.
18	/// </remarks>
19	[Collection(ProcessEnvironmentCollection.Name)]
20	public sealed class CliTempVariablesTests
21	{
22	    private const string Folder = "/scripted/cli-temp-folder";
23	
24	    private const string Fallback = "/scripted/cli-temp-fallback";
25	
26	    /// <summary>
27	    /// The name list holds the five chain names once each: CliBrainSlotChatClient (QUADBRAIN_CLI, ONESHOT), Codex
28	    /// (CODEX_ONESHOT, CODEX_TRIAGE), one-shot (ONESHOT, CODEX_ONESHOT, CODEX_TRIAGE) and Grok (GROK_ONESHOT, ONESHOT).
29	    /// </summary>
30	    [Fact]
31	    public void Names_HoldEveryChainNameOnce()
32	    {
33	        string[] expected =
34	        [
35	            "MCPSERVER_CODEX_ONESHOT_TEMP",
36	            "MCPSERVER_CODEX_TRIAGE_TEMP",
37	            "MCPSERVER_GROK_ONESHOT_TEMP",
38	            "MCPSERVER_ONESHOT_TEMP",
39	            "MCPSERVER_QUADBRAIN_CLI_TEMP",
40	        ];
41	
42	        Assert.Equal(expected, Names.Order(StringComparer.Ordinal));
43	    }
44	
45	    /// <summary>Mock gate positive control: a scripted snapshot with every name at the folder passes.</summary>
46	    [Fact]
47	    public void ScriptedSnapshot_EveryNameAtTheFolder_Passes() =>
48	        AssertAllAt(Scripted(_ => Folder), Folder);
49	
50	    /// <summary>
51	    /// Mock gate negative controls: a snapshot missing one name, one with a name at another folder, and one with a
52	    /// name unset are each rejected, inside a passing harness.
53	    /// </summary>
54	    [Fact]
55	    public void ScriptedSnapshot_MissingOrWrongName_IsRejectedInsidePassingHarness()
56	    {
57	        var missing = Scripted(_ => Folder);
58	        missing.Remove("MCPSERVER_CODEX_TRIAGE_TEMP");
59	        var elsewhere = Scripted(name => name == "MCPSERVER_GROK_ONESHOT_TEMP" ? "/scripted/other-folder" : Folder);
60	        var unset = Scripted(name => name == "MCPSERVER_ONESHOT_TEMP" ? null : Folder);
61	
62	        Assert.NotNull(Record.Exception(() => AssertAllAt(missing, Folder)));
63	        Assert.NotNull(Record.Exception(() => AssertAllAt(elsewhere, Folder)));
64	        Assert.NotNull(Record.Exception(() => AssertAllAt(unset, Folder)));
65	    }
66	
67	    /// <summary>
68	    /// Mock gate positive control: a scripted snapshot with the primary name at the folder and every other name at the
69	    /// fallback folder passes, for each name as the primary.
70	    /// </summary>
71	    /// <param name="primaryName">The name read first.</param>
72	    [Theory]
73	    [InlineData("MCPSERVER_QUADBRAIN_CLI_TEMP")]
74	    [InlineData("MCPSERVER_ONESHOT_TEMP")]
75	    [InlineData("MCPSERVER_CODEX_ONESHOT_TEMP")]
76	    public void ScriptedChain_PrimaryAtFolderOthersAtFallback_Passes(string primaryName) =>
77	        AssertChainAt(Scripted(name => name == primaryName ? Folder : Fallback), primaryName, Folder, Fallback);
78	
79	    /// <summary>
80	    /// Mock gate negative controls: the primary name at the fallback folder, another name at the primary folder, a
81	    /// missing name, an unset name, a fallback folder equal to the primary folder, and a primary name outside the
82	    /// chain are each rejected, inside a passing harness.
83	    /// </summary>
84	    [Fact]
85	    public void ScriptedChain_WrongSnapshot_IsRejectedInsidePassingHarness()
86	    {
87	        const string primary = "MCPSERVER_QUADBRAIN_CLI_TEMP";
88	        var good = Scripted(name => name == primary ? Folder : Fallback);
89	        var primaryAtFallback = Scripted(_ => Fallback);
90	        var otherAtFolder = Scripted(name => name == primary || name == "MCPSERVER_ONESHOT_TEMP" ? Folder : Fallback);
91	        var missing = Scripted(name => name == primary ? Folder : Fallback);
92	        missing.Remove("MCPSERVER_GROK_ONESHOT_TEMP");
93	        var unset = Scripted(name => name == primary ? Folder : name == "MCPSERVER_CODEX_TRIAGE_TEMP" ? null : Fallback);
94	        var sameFolders = Scripted(_ => Folder);
95	
96	        Assert.NotNull(Record.Exception(() => AssertChainAt(primaryAtFallback, primary, Folder, Fallback)));
97	        Assert.NotNull(Record.Exception(() => AssertChainAt(otherAtFolder, primary, Folder, Fallback)));
98	        Assert.NotNull(Record.Exception(() => AssertChainAt(missing, primary, Folder, Fallback)));
99	        Assert.NotNull(Record.Exception(() => AssertChainAt(unset, primary, Folder, Fallback)));
100	        Assert.NotNull(Record.Exception(() => AssertChainAt(sameFolders, primary, Folder, Folder)));
101	        Assert.NotNull(Record.Exception(() => AssertChainAt(good, "MCPSERVER_NOT_A_CHAIN_NAME", Folder, Fallback)));
102	    }
103	
104	    /// <summary>Mock gate positive control: equal before and after snapshots, an unset name included, pass.</summary>
105	    [Fact]
106	    public void ScriptedRestore_EqualSnapshots_Pass() =>
107	        AssertRestored(Scripted(Prior), Scripted(Prior));
108	
109	    /// <summary>
110	    /// Mock gate negative controls: an after snapshot that left one name at the folder, one that set a previously
111	    /// unset name, and one missing a name are each rejected, inside a passing harness.
112	    /// </summary>
113	    [Fact]
114	    public void ScriptedRestore_UnrestoredName_IsRejectedInsidePassingHarness()
115	    {
116	        var before = Scripted(Prior);
117	        var leftSet = Scripted(name => name == "MCPSERVER_QUADBRAIN_CLI_TEMP" ? Folder : Prior(name));
118	        var newlySet = Scripted(name => name == "MCPSERVER_GROK_ONESHOT_TEMP" ? Folder : Prior(name));
119	        var missing = Scripted(Prior);
120	        missing.Remove("MCPSERVER_ONESHOT_TEMP");
121	
122	        Assert.NotNull(Record.Exception(() => AssertRestored(before, leftSet)));
123	        Assert.NotNull(Record.Exception(() => AssertRestored(before, newlySet)));
124	        Assert.NotNull(Record.Exception(() => AssertRestored(before, missing)));
125	    }
126	
127	    /// <summary>
128	    /// Binding: the helper points every name at one new folder under the official temporary folder while the body
129	    /// runs, then restores every scripted earlier value (an unset name included) and deletes the folder. The test
130	    /// writes the process environment and restores the ambient values, so it is an integration test.
131	    /// </summary>
132	    /// <returns>A task that completes when the assertions have run.</returns>
133	    [Fact]
134	    [Trait("Category", "Integration")]
135	    public async Task RunWithTestFolderAsync_PointsEveryNameAtItsFolderThenRestoresThem()
136	    {
137	        var ambient = Snapshot();
138	        try
139	        {
140	            SetAll(Prior);
141	            var before = Snapshot();
142	            string? seenFolder = null;
143	            Dictionary<string, string?>? inside = null;
144	            var existed = false;
145	
146	            await RunWithTestFolderAsync(folder =>
147	            {
148	                seenFolder = folder;
149	                inside = Snapshot();
150	                existed = Directory.Exists(folder);
151	                return Task.CompletedTask;
152	            }).ConfigureAwait(true);
153	
154	            Assert.NotNull(seenFolder);
155	            Assert.NotNull(inside);
156	            AssertAllAt(inside, seenFolder);
157	            Assert.True(existed);
158	            Assert.StartsWith(Path.GetFullPath(Path.GetTempPath()), Path.GetFullPath(seenFolder), StringComparison.OrdinalIgnoreCase);
159	            Assert.False(Directory.Exists(seenFolder));
160	            AssertRestored(before, Snapshot());
161	        }
162	        finally
163	        {
164	            SetAll(name => ambient[name]);
165	        }
166	    }
167	
168	    /// <summary>
169	    /// Binding: when the body throws, the exception reaches the caller and the helper still restores every scripted
170	    /// earlier value and deletes the folder. The test writes the process environment and restores the ambient
171	    /// values, so it is an integration test.
172	    /// </summary>
173	    /// <returns>A task that completes when the assertions have run.</returns>
174	    [Fact]
175	    [Trait("Category", "Integration")]
176	    public async Task RunWithTestFolderAsync_BodyThrows_StillRestoresAndDeletes()
177	    {
178	        var ambient = Snapshot();
179	        try
180	        {
181	            SetAll(Prior);
182	            var before = Snapshot();
183	            string? seenFolder = null;
184	
185	            await Assert.ThrowsAsync<InvalidOperationException>(() => RunWithTestFolderAsync(folder =>
186	            {
187	                seenFolder = folder;
188	                throw new InvalidOperationException("scripted body failure");
189	            })).ConfigureAwait(true);
190	
191	            Assert.NotNull(seenFolder);
192	            Assert.False(Directory.Exists(seenFolder));
193	            AssertRestored(before, Snapshot());
194	        }
195	        finally
196	        {
197	            SetAll(name => ambient[name]);
198	        }
199	    }
200	
201	    private static void SetAll(Func<string, string?> value)
202	    {
203	        foreach (var name in Names)
